#!/usr/bin/env python3
"""Add three opt-in switches for the L00 twins func_L00_003F6308 and func_L00_003A91A0.

- -frac2-gcse-hash-fp-117 (gcse.c hash_expr_1): the frame-pointer REG hashes 117 further on, which
  changes PRE's bucket walk and so the reaching registers' (and spill slots') order. Offsets
  113..120 all fit retail's slot order for both twins; 117 is fixed here, like -frac2-gcse-hash-111.
- -frac2-giv-pair-init (loop.c strength_reduce): when one biv has two reduced givs with initial
  values BASE+PRODUCT and (BASE+C)+PRODUCT, the first is computed as PRODUCT+BASE and the second
  as (BASE+PRODUCT)+C.
- -frac2-cse2-skip-temp-sum (cse.c cse_insn): after loop, a register+register sum set into a
  non-user pseudo that has several sets is not recorded.

Forced on they change 100, 2 and 10 functions (111 together). The last two were fitted to retail's
bytes. Opt-in per-unit models under the owner's standard of 12 November 2026. Default compilation
is unchanged.

Usage: l00_rules.py <gcc directory>
"""
import sys
from pathlib import Path

HUNKS = {'gcse.c': [('      {\n\tregister int regno = REGNO (x);\n\thash += ((unsigned) REG << 7) + regno;\n\treturn hash;\n      }\n', '      {\n\tregister int regno = REGNO (x);\n\thash += ((unsigned) REG << 7) + regno;\n\t/* RAC2: -frac2-gcse-hash-fp-117 hashes the frame pointer 117\n\t   buckets further on, as if frame addresses were based on\n\t   register 118 instead of register 1.  Only the order of the\n\t   expression table changes, and with it the order in which PRE\n\t   creates its reaching registers (and so their spill slots).  */\n\tif (flag_rac2_gcse_hash_fp_117 && regno == FRAME_POINTER_REGNUM)\n\t  hash += 117;\n\treturn hash;\n      }\n')], 'loop.c': [('struct recombine_givs_stats;\nstatic int find_life_end PROTO((rtx,  struct recombine_givs_stats *, rtx, rtx));\nstatic void recombine_givs PROTO((struct iv_class *, rtx, rtx, int));\nstatic int product_cheap_p PROTO((rtx, rtx));\nstatic int maybe_eliminate_biv PROTO((struct iv_class *, rtx, rtx, int, int, int));\nstatic int maybe_eliminate_biv_1 PROTO((rtx, rtx, struct iv_class *, int, rtx));\n', 'struct recombine_givs_stats;\nstatic int find_life_end PROTO((rtx,  struct recombine_givs_stats *, rtx, rtx));\nstatic void recombine_givs PROTO((struct iv_class *, rtx, rtx, int));\nrtx rac2_giv_pair_init ();\nstatic int product_cheap_p PROTO((rtx, rtx));\nstatic int maybe_eliminate_biv PROTO((struct iv_class *, rtx, rtx, int, int, int));\nstatic int maybe_eliminate_biv_1 PROTO((rtx, rtx, struct iv_class *, int, rtx));\n'), ("\t      /* Add code at loop start to initialize giv's reduced reg.  */\n\n\t      emit_iv_add_mult (bl->initial_value, v->mult_val,\n\t\t\t\tv->add_val, v->new_reg, loop_start);\n\t    }\n\t}\n", "\t      /* Add code at loop start to initialize giv's reduced reg.  */\n\n\t      emit_iv_add_mult (bl->initial_value, v->mult_val,\n\t\t\t\trac2_giv_pair_init (bl, v), v->new_reg,\n\t\t\t\tloop_start);\n\t    }\n\t}\n"), ('    }\n}\n\x0c\n/* EMIT code before INSERT_BEFORE to set REG = B * M + A.  */\n\nvoid\n', '    }\n}\n\x0c\n/* RAC2: -frac2-giv-pair-init.  When one biv has two reduced givs whose\n   initial values are BASE + PRODUCT and (BASE + C) + PRODUCT (BASE a\n   register, PRODUCT an invariant product, C a constant), compute the\n   first as PRODUCT + BASE and the second as (BASE + PRODUCT) + C, instead\n   of BASE + PRODUCT and BASE + (PRODUCT + C).  Returns the value to\n   expand for giv V of class BL.  */\nrtx\nrac2_giv_pair_init (bl, v)\n     struct iv_class *bl;\n     struct induction *v;\n{\n  rtx a = v->add_val;\n  struct induction *s;\n  int with_const;\n  rtx r, m, c;\n\n  if (! flag_rac2_giv_pair_init)\n    return a;\n  if (GET_CODE (a) != PLUS || GET_CODE (XEXP (a, 1)) != MULT)\n    return a;\n  m = XEXP (a, 1);\n  if (GET_CODE (XEXP (a, 0)) == REG)\n    with_const = 0, r = XEXP (a, 0), c = 0;\n  else if (GET_CODE (XEXP (a, 0)) == PLUS\n\t   && GET_CODE (XEXP (XEXP (a, 0), 0)) == REG\n\t   && GET_CODE (XEXP (XEXP (a, 0), 1)) == CONST_INT)\n    with_const = 1, r = XEXP (XEXP (a, 0), 0), c = XEXP (XEXP (a, 0), 1);\n  else\n    return a;\n\n  for (s = bl->giv; s; s = s->next_iv)\n    {\n      rtx sa = s->add_val;\n\n      if (s == v || s->ignore || s->same\n\t  || ! rtx_equal_p (s->mult_val, v->mult_val)\n\t  || GET_CODE (sa) != PLUS || ! rtx_equal_p (XEXP (sa, 1), m))\n\tcontinue;\n      if (with_const && rtx_equal_p (XEXP (sa, 0), r))\n\treturn gen_rtx_PLUS (GET_MODE (a),\n\t\t\t     gen_rtx_PLUS (GET_MODE (a), r, m), c);\n      if (! with_const && GET_CODE (XEXP (sa, 0)) == PLUS\n\t  && rtx_equal_p (XEXP (XEXP (sa, 0), 0), r)\n\t  && GET_CODE (XEXP (XEXP (sa, 0), 1)) == CONST_INT)\n\treturn gen_rtx_PLUS (GET_MODE (a), m, r);\n    }\n  return a;\n}\n\n/* EMIT code before INSERT_BEFORE to set REG = B * M + A.  */\n\nvoid\n')], 'cse.c': [("\t  && REG_N_SETS (REGNO (dest)) != 1)\n\tsets[i].src_volatile = 1;\n\n#if 0\n      /* It is no longer clear why we used to do this, but it doesn't\n\t appear to still be needed.  So let's try without it since this\n", "\t  && REG_N_SETS (REGNO (dest)) != 1)\n\tsets[i].src_volatile = 1;\n\n      /* RAC2: -frac2-cse2-skip-temp-sum.  After loop, do not record the\n\t sum of two registers computed into a compiler temporary that is\n\t set more than once (the initial value of a reduced giv), so a\n\t later equal sum is computed again instead of being copied from\n\t the induction register.  */\n      if (flag_rac2_cse2_skip_temp_sum && rac2_cse_after_loop\n\t  && GET_CODE (src) == PLUS\n\t  && GET_CODE (XEXP (src, 0)) == REG\n\t  && GET_CODE (XEXP (src, 1)) == REG\n\t  && GET_CODE (dest) == REG\n\t  && REGNO (dest) >= FIRST_PSEUDO_REGISTER\n\t  && ! REG_USERVAR_P (dest)\n\t  && REG_N_SETS (REGNO (dest)) != 1)\n\tsets[i].src_volatile = 1;\n\n#if 0\n      /* It is no longer clear why we used to do this, but it doesn't\n\t appear to still be needed.  So let's try without it since this\n")], 'toplev.c': [('/* RAC2: opt-in, force GCSE expression hash table to 111 buckets.  */\nint flag_rac2_gcse_hash_111 = 0;\n\n/* RAC2: opt-in, tie-break memory stores by lower displacement.  */\nint flag_rac2_sched_store_offset = 0;\n', '/* RAC2: opt-in, force GCSE expression hash table to 111 buckets.  */\nint flag_rac2_gcse_hash_111 = 0;\n\n/* RAC2: opt-in, GCSE hashes the frame pointer 117 buckets further on.  */\nint flag_rac2_gcse_hash_fp_117 = 0;\n\n/* RAC2: opt-in, paired giv initial values share base + product.  */\nint flag_rac2_giv_pair_init = 0;\n\n/* RAC2: opt-in, cse2 does not record a register sum set into a\n   multiply-set temporary.  */\nint flag_rac2_cse2_skip_temp_sum = 0;\n\n/* RAC2: opt-in, tie-break memory stores by lower displacement.  */\nint flag_rac2_sched_store_offset = 0;\n'), ('   "Prefer lower displacement for tied memory stores to same base"},\n  {"rac2-gcse-hash-111", &flag_rac2_gcse_hash_111, 1,\n   "Force GCSE expression hash table to 111 buckets"},\n  {"rac2-delay-no-split-hi", &flag_rac2_delay_no_split_hi, 1,\n   "Keep split high-part address loads out of conditional delay slots"},\n  {"rac2-caller-reg-order", &flag_rac2_caller_reg_order, 1,\n', '   "Prefer lower displacement for tied memory stores to same base"},\n  {"rac2-gcse-hash-111", &flag_rac2_gcse_hash_111, 1,\n   "Force GCSE expression hash table to 111 buckets"},\n  {"rac2-gcse-hash-fp-117", &flag_rac2_gcse_hash_fp_117, 1,\n   "Add 117 to the GCSE expression hash of the frame pointer"},\n  {"rac2-giv-pair-init", &flag_rac2_giv_pair_init, 1,\n   "Compute paired giv initial values as product+base and (base+product)+const"},\n  {"rac2-cse2-skip-temp-sum", &flag_rac2_cse2_skip_temp_sum, 1,\n   "After loop, do not record a register sum set into a multiply-set temporary"},\n  {"rac2-delay-no-split-hi", &flag_rac2_delay_no_split_hi, 1,\n   "Keep split high-part address loads out of conditional delay slots"},\n  {"rac2-caller-reg-order", &flag_rac2_caller_reg_order, 1,\n')], 'flags.h': [('extern int flag_rac2_delay_no_split_hi;\n/* RAC2: force GCSE expression hash table to 111 buckets.  */\nextern int flag_rac2_gcse_hash_111;\n/* RAC2: tie-break memory stores by lower displacement.  */\nextern int flag_rac2_sched_store_offset;\n/* RAC2: tie-break stack address computations by higher displacement.  */\n', 'extern int flag_rac2_delay_no_split_hi;\n/* RAC2: force GCSE expression hash table to 111 buckets.  */\nextern int flag_rac2_gcse_hash_111;\n/* RAC2: GCSE hashes the frame pointer 117 buckets further on.  */\nextern int flag_rac2_gcse_hash_fp_117;\n/* RAC2: paired giv initial values share base + product.  */\nextern int flag_rac2_giv_pair_init;\n/* RAC2: cse2 does not record a register sum set into a multiply-set\n   temporary.  */\nextern int flag_rac2_cse2_skip_temp_sum;\n/* RAC2: tie-break memory stores by lower displacement.  */\nextern int flag_rac2_sched_store_offset;\n/* RAC2: tie-break stack address computations by higher displacement.  */\n')]}


def replace_once(text: str, before: str, after: str, label: str) -> str:
    if text.count(before) != 1:
        raise ValueError(f"{label}: expected one insertion point, found {text.count(before)}")
    return text.replace(before, after)


def patch(gcc: Path) -> None:
    sources = {name: (gcc / name).read_text(encoding="latin-1") for name in HUNKS}
    if any("flag_rac2_giv_pair_init" in text for text in sources.values()):
        raise ValueError("l00 rules already present")
    for name, hunks in HUNKS.items():
        for k, (old, new) in enumerate(hunks):
            sources[name] = replace_once(sources[name], old, new, f"{name} hunk {k}")
    for name, text in sources.items():
        (gcc / name).write_text(text, encoding="latin-1", newline="")


if __name__ == "__main__":
    patch(Path(sys.argv[1]))
